{
  "avaliacoes": [
    {
      "id": "Ef07338e15a70351d",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Na gestão de backlog, KPIs apoiados por dados de alta qualidade podem ser usados para dar foco à redução do backlog.",
          "trechos": [
            "Ef07338e15a70351d:0:700"
          ],
          "condicoes": [
            "aplica-se a instalações onde o backlog de manutenção é baixo ou está sendo reduzido",
            "depende de dados de boa qualidade"
          ],
          "limites": [
            "o trecho descreve prática observada/indicada em contexto UK offshore, não um requisito brasileiro",
            "não define quais KPIs devem ser usados nem metas numéricas"
          ]
        },
        {
          "proposicao": "Metas móveis de backlog e pontos de gatilho podem ser usados para acionar ações gerenciais, como reforço de recursos, campanhas de manutenção e revisão de cargas de projetos que competem com a manutenção planejada.",
          "trechos": [
            "Ef07338e15a70351d:0:700",
            "Ef07338e15a70351d:700:1395"
          ],
          "condicoes": [
            "quando níveis de backlog atingem pontos previamente definidos",
            "em contexto de disputa por recursos, leitos e suporte logístico"
          ],
          "limites": [
            "o texto não estabelece valores de gatilho",
            "as ações citadas são exemplos, não lista exaustiva"
          ]
        },
        {
          "proposicao": "O diferimento de manutenção reconhece potencial degradação de SCE e deveria prever compensação para a degradação e para o aumento potencial de risco; a gestão deveria buscar eliminar causas que levam a diferimentos.",
          "trechos": [
            "Ef07338e15a70351d:1395:2093",
            "Ef07338e15a70351d:2093:2331"
          ],
          "condicoes": [
            "quando a tarefa não recebe recursos no sistema de gestão",
            "especialmente para manutenção e testes postergados"
          ],
          "limites": [
            "o próprio texto relata desempenho consistentemente fraco nessa área, portanto descreve problema recorrente e não controle universalmente eficaz",
            "não detalha método de avaliação de risco nem medidas compensatórias específicas"
          ]
        }
      ]
    },
    {
      "id": "E3549e700bde5a3f1",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Acompanhamento de indicador de falhas por testes em elementos críticos de segurança operacional é apresentado como prática possível para monitorar desempenho de sistemas críticos.",
          "trechos": [
            "E3549e700bde5a3f1:693:1393"
          ],
          "condicoes": [
            "relacionado a elementos críticos como detecção de fogo e gás, bombas de incêndio, válvulas e BOP",
            "no contexto de práticas adotadas pelo PSA e avaliadas pela ANP"
          ],
          "limites": [
            "o texto trata isso como boa prática/ferramenta possível, não como obrigação geral",
            "não define critério de aceitação ou periodicidade"
          ]
        },
        {
          "proposicao": "Indicadores de manutenção, incluindo backlog preventivo e corretivo de elementos críticos e não críticos, podem ser acompanhados para avaliar a gestão da manutenção.",
          "trechos": [
            "E3549e700bde5a3f1:1393:2089"
          ],
          "condicoes": [
            "com segregação entre elementos críticos e não críticos",
            "com separação de horas de manutenção por tipo de atividade"
          ],
          "limites": [
            "o trecho não define fórmula detalhada para todos os indicadores",
            "não estabelece limite aceitável de backlog"
          ]
        },
        {
          "proposicao": "Indicadores similares podem ser usados para avaliar impactos do envelhecimento da instalação, sobretudo perto do fim da vida de projeto e em transferências de instalações.",
          "trechos": [
            "E3549e700bde5a3f1:2089:2325"
          ],
          "condicoes": [
            "principalmente em processos de envelhecimento",
            "especialmente próximos ao final da vida útil de projeto ou em transferência de instalações"
          ],
          "limites": [
            "o texto afirma possibilidade de uso, não comprovação de desempenho em todos os cenários",
            "não detalha quais ajustes metodológicos são necessários"
          ]
        }
      ]
    },
    {
      "id": "Ec60fea04bada10c6",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Na investigação da P-53, foi evidenciado backlog de manutenção incompatível com a disponibilidade de pessoas a bordo, indicando insuficiência de recursos para execução dos serviços.",
          "trechos": [
            "Ec60fea04bada10c6:698:1384",
            "Ec60fea04bada10c6:1384:2084"
          ],
          "condicoes": [
            "constatação feita no contexto específico das duas últimas auditorias citadas e da investigação do evento",
            "referente ao sistema de tratamento de água produzida da instalação"
          ],
          "limites": [
            "é achado de caso específico, não regra geral para todas as plataformas",
            "o trecho não quantifica backlog nem efetivo necessário"
          ]
        },
        {
          "proposicao": "A degradação e indisponibilidade de equipamentos foram associadas a má disponibilização e planejamento de recursos para o sistema de tratamento de água.",
          "trechos": [
            "Ec60fea04bada10c6:698:1384"
          ],
          "condicoes": [
            "no contexto do estado de degradação observado em alguns equipamentos do sistema de água produzida"
          ],
          "limites": [
            "trata-se de inferência da investigação para esse sistema específico",
            "não descreve metodologia geral de planejamento de recursos"
          ]
        },
        {
          "proposicao": "A indisponibilidade de equipamentos teve consequências operacionais como maior controle manual pelos operadores, falta de informação de processo, redução da capacidade de separação e alinhamentos operacionais conforme o grau API do óleo.",
          "trechos": [
            "Ec60fea04bada10c6:1384:2084"
          ],
          "condicoes": [
            "ligado à indisponibilidade e degradação dos equipamentos do sistema analisado"
          ],
          "limites": [
            "as consequências listadas são do caso investigado",
            "não há hierarquização quantitativa do impacto de cada consequência"
          ]
        }
      ]
    },
    {
      "id": "E1f5ff0f8eb3fc4e2",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Um sistema de gestão de manutenção pode ser usado para detalhar, programar, executar e registrar atividades, com referência cruzada entre tarefas críticas e padrões de desempenho e uso de datas programadas para planejamento, programação e backlog.",
          "trechos": [
            "E1f5ff0f8eb3fc4e2:0:698"
          ],
          "condicoes": [
            "no exemplo descrito, tarefas safety-critical recebem prioridade específica",
            "as datas registradas são usadas como base do processo"
          ],
          "limites": [
            "o trecho descreve arranjo organizacional e uso de SAP em um caso observado",
            "não implica que toda instalação deva usar a mesma ferramenta ou categorização"
          ]
        },
        {
          "proposicao": "O planejamento pode ser estruturado em horizontes de longo, médio e curto prazo, com refinamento progressivo até planos semanais e diários ajustados por restrições locais como efetivo e atrasos imprevistos.",
          "trechos": [
            "E1f5ff0f8eb3fc4e2:0:698",
            "E1f5ff0f8eb3fc4e2:698:1391"
          ],
          "condicoes": [
            "há interação entre planejamento onshore e offshore",
            "os planos detalhados reagem a questões locais em andamento"
          ],
          "limites": [
            "os horizontes temporais citados pertencem ao exemplo analisado",
            "o texto não compara essa estrutura com alternativas"
          ]
        },
        {
          "proposicao": "No processo descrito, diferimentos de manutenção crítica exigem aprovação, rastreio das mudanças de data e identificação de mitigação para assegurar segurança e integridade contínuas; tarefas diferidas não entram no backlog, mas a onda de trabalho gerada é acompanhada.",
          "trechos": [
            "E1f5ff0f8eb3fc4e2:698:1391",
            "E1f5ff0f8eb3fc4e2:1391:2091"
          ],
          "condicoes": [
            "aplica-se ao processo de diferimento e reprogramação descrito",
            "para tarefas CAT 1/SCE há aprovação do custodiante do sistema"
          ],
          "limites": [
            "o tratamento de diferidos fora do backlog é específico do processo relatado",
            "não detalha critérios de risco para aceitar o diferimento"
          ]
        }
      ]
    },
    {
      "id": "Ec60e3fa1dc1dd714",
      "pertinente": true,
      "tipo": "opiniao",
      "achados": [
        {
          "proposicao": "Paradas programadas de manutenção são apresentadas como mobilização de grande número de trabalhadores especializados em curto período para manutenção majoritariamente preventiva da planta industrial.",
          "trechos": [
            "Ec60e3fa1dc1dd714:0:700",
            "Ec60e3fa1dc1dd714:1400:2092"
          ],
          "condicoes": [
            "no contexto de plantas industriais de produção offshore",
            "como descrição introdutória de trabalho acadêmico"
          ],
          "limites": [
            "é formulação descritiva de introdução/resumo, sem comprovação empírica nesse trecho",
            "não detalha critérios de dimensionamento de recursos nem aplicabilidade a todos os cenários offshore"
          ]
        },
        {
          "proposicao": "O estudo se propõe a analisar todas as etapas de uma parada programada, do planejamento ao encerramento, e a sugerir melhorias a partir da comparação entre prática empresarial e modelo teórico.",
          "trechos": [
            "Ec60e3fa1dc1dd714:700:1400",
            "Ec60e3fa1dc1dd714:1400:2092"
          ],
          "condicoes": [
            "baseado em estudo de caso de parada offshore ocorrida em 2015"
          ],
          "limites": [
            "o trecho apresenta objetivo e método resumidos, não resultados",
            "não oferece, aqui, achados técnicos suficientes sobre critérios de programação, backlog ou diferimento"
          ]
        }
      ]
    },
    {
      "id": "E0d958719befe3022",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Regimes de integridade de FPSOs/FSUs costumam combinar inspeções periódicas prescritivas com esquemas de inspeção baseados em risco para gerir a integridade da instalação.",
          "trechos": [
            "E0d958719befe3022:692:1386"
          ],
          "condicoes": [
            "no contexto de FPSOs/FSUs operando no UKCS",
            "especialmente relevante para unidades além da vida de projeto original"
          ],
          "limites": [
            "o texto descreve prática usual e contexto regulatório do Reino Unido",
            "não especifica como selecionar o equilíbrio entre inspeção prescritiva e RBI"
          ]
        },
        {
          "proposicao": "Intervenções recentes identificaram como problema a falta de sistema de gestão de integridade adequado para identificar e mitigar questões de envelhecimento e fim de vida, além de falhas em aderir ao programa definido de integridade.",
          "trechos": [
            "E0d958719befe3022:1386:2085"
          ],
          "condicoes": [
            "relacionado à gestão de integridade estrutural e marítima de FPSOs/FSUs"
          ],
          "limites": [
            "são lições aprendidas de intervenções e não evidenciam prevalência universal",
            "o trecho não detalha conteúdo mínimo de um sistema adequado"
          ]
        },
        {
          "proposicao": "A falta de visibilidade do backlog de inspeção de integridade dentro do backlog geral de manutenção de SECE e os repetidos diferimentos de manutenção preventiva de SECE são apontados como questões relevantes.",
          "trechos": [
            "E0d958719befe3022:2085:2377"
          ],
          "condicoes": [
            "aplica-se a backlog de casco submerso, tanques de carga e lastro, amarrações e itens correlatos"
          ],
          "limites": [
            "o trecho apenas identifica o problema e não traz método de integração ou priorização",
            "contexto regulatório e operacional é do UKCS"
          ]
        }
      ]
    }
  ],
  "concluir": false,
